'use strict';

function loadContractsDiagnostics() {
  try {
    return require('@pulse-compute/wasm-contracts/diagnostics');
  } catch (error) {
    if (error && error.code === 'MODULE_NOT_FOUND' && String(error.message).includes('@pulse-compute/wasm-contracts')) {
      return require('../../../contracts/src/diagnostics.js');
    }
    throw error;
  }
}

const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { getDefaultArtifactsDir } = require('@pulse-compute/wasm-build-support/artifacts-dir');
const { spawnSync } = require('node:child_process');
const { PACKAGE_VERSION, normalizeArtifact } = loadContractsDiagnostics();
const { resolveAsc } = require('@pulse-compute/wasm-build-support/assemblyscript-compile');

const ASSEMBLYSCRIPT_WASM_SMOKE_VERSION = 'pulsewasm.assemblyscript-wasm-smoke.v1';
const SMOKE_WASM_FILE = 'generated/wasm-smoke/pulsewasm-local-smoke.wasm';
const SMOKE_WAT_FILE = 'generated/wasm-smoke/pulsewasm-local-smoke.wat';
const SMOKE_RUNNER_FILE = 'generated/as-smoke/smoke-runner.as.ts';

function sha256Buffer(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

function sha256Text(text) {
  return crypto.createHash('sha256').update(text, 'utf8').digest('hex');
}

function truncate(value, max = 20000) {
  const text = String(value || '');
  if (text.length <= max) return text;
  return `${text.slice(0, max)}\n... <truncated ${text.length - max} chars>`;
}

function stripAnsi(value) {
  return String(value || '').replace(/\u001b\[[0-9;]*m/g, '');
}

function parseAscWarnings(stderr) {
  const text = stripAnsi(stderr);
  const warnings = [];
  const regex = /WARNING\s+(AS\d+):\s+([^\n]+)(?:.|\n)*?in ([^\n]+)\((\d+),(\d+)\)/g;
  let match;
  while ((match = regex.exec(text))) {
    warnings.push({
      code: match[1],
      message: match[2].trim(),
      file: match[3],
      line: Number(match[4]),
      column: Number(match[5])
    });
  }
  if (warnings.length === 0 && /WARNING\s+AS\d+:/m.test(text)) {
    warnings.push({ code: 'AS_WARNING', message: 'AssemblyScript emitted one or more warnings. Inspect result.stderr for details.' });
  }
  return warnings;
}

function assemblyScriptVersion(cwd) {
  try {
    const packageJson = require.resolve('assemblyscript/package.json', { paths: [cwd] });
    const pkg = JSON.parse(fs.readFileSync(packageJson, 'utf8'));
    return pkg.version;
  } catch (_) {
    return undefined;
  }
}

function fileRecord(filePath, cwd, kind) {
  const buffer = fs.readFileSync(filePath);
  return {
    file: path.relative(cwd, filePath).replace(/\\/g, '/'),
    kind,
    bytes: buffer.length,
    sha256: sha256Buffer(buffer)
  };
}

function writeStagedFiles(stagingDir, shape, core, smokeRunnerText) {
  const allFiles = [];
  if (shape && Array.isArray(shape.files)) allFiles.push(...shape.files);
  if (core && Array.isArray(core.files)) allFiles.push(...core.files);

  const byFile = new Map();
  for (const file of allFiles) byFile.set(file.file, file.text);
  byFile.set(SMOKE_RUNNER_FILE, smokeRunnerText);

  for (const [file, text] of byFile.entries()) {
    const abs = path.join(stagingDir, file);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, text, 'utf8');
  }

  return Array.from(byFile.entries()).map(([file, text]) => ({
    file,
    bytes: Buffer.byteLength(text, 'utf8'),
    sha256: sha256Text(text)
  }));
}

function buildSmokeRunnerSource() {
  return `/*\n * Generated by PulseWasm Phase 9F.\n * Do not edit by hand.\n *\n * This local smoke runner uses AssemblyScript string literals internally so the\n * host-side string/memory ABI remains intentionally unlocked.\n */\nimport {\n  METHOD_GET,\n  METHOD_POST,\n  MODE_NORMAL,\n  STEP_INVOKE,\n  ROUTE_COUNT,\n  EXECUTION_ENTRY_COUNT,\n  HANDLER_BINDING_COUNT,\n  matchRouteId,\n  scanNextEntry,\n  createDispatchState,\n  stepDispatchState,\n  continueNormal,\n  defaultStatusForStepResult,\n  handlerSlotExists,\n  invokeMiddlewareHandlerBySlot,\n  invokeRouteHandlerBySlot,\n  invokeLifecycleHandlerBySlot,\n  invokeChannelHandlerBySlot\n} from '../as/index.as'\n\nexport function smoke_route_count(): i32 { return ROUTE_COUNT }\nexport function smoke_execution_entry_count(): i32 { return EXECUTION_ENTRY_COUNT }\nexport function smoke_handler_binding_count(): i32 { return HANDLER_BINDING_COUNT }\n\nexport function smoke_match_get_realtime(): i32 { return matchRouteId(METHOD_GET, \"/realtime/abc\") }\nexport function smoke_match_post_compute(): i32 { return matchRouteId(METHOD_POST, \"/compute/42\") }\nexport function smoke_match_missing(): i32 { return matchRouteId(METHOD_GET, \"/missing\") }\n\nexport function smoke_scan_get_realtime_first_entry(): i32 { return scanNextEntry(0, MODE_NORMAL, METHOD_GET, \"/realtime/abc\") }\n\nexport function smoke_step_get_realtime_first_entry(): i32 {\n  const state = createDispatchState(METHOD_GET, \"/realtime/abc\")\n  const result = stepDispatchState(state)\n  return result == STEP_INVOKE ? state.currentEntryIndex : -1000 - result\n}\n\nexport function smoke_get_realtime_second_entry_after_next(): i32 {\n  const state = createDispatchState(METHOD_GET, \"/realtime/abc\")\n  stepDispatchState(state)\n  continueNormal(state)\n  const result = stepDispatchState(state)\n  return result == STEP_INVOKE ? state.currentEntryIndex : -1000 - result\n}\n\nexport function smoke_get_realtime_route_after_two_nexts(): i32 {\n  const state = createDispatchState(METHOD_GET, \"/realtime/abc\")\n  stepDispatchState(state)\n  continueNormal(state)\n  stepDispatchState(state)\n  continueNormal(state)\n  const result = stepDispatchState(state)\n  return result == STEP_INVOKE ? state.currentRouteRuntimeId : -1000 - result\n}\n\nexport function smoke_post_compute_route_after_next(): i32 {\n  const state = createDispatchState(METHOD_POST, \"/compute/42\")\n  stepDispatchState(state)\n  continueNormal(state)\n  const result = stepDispatchState(state)\n  return result == STEP_INVOKE ? state.currentRouteRuntimeId : -1000 - result\n}\n\nexport function smoke_missing_after_auth_next_status(): i32 {\n  const state = createDispatchState(METHOD_GET, \"/missing\")\n  stepDispatchState(state)\n  continueNormal(state)\n  const result = stepDispatchState(state)\n  return defaultStatusForStepResult(result)\n}\n\nexport function smoke_handler_slot_exists_auth(): i32 { return handlerSlotExists(0) ? 1 : 0 }\nexport function smoke_invoke_middleware_auth(): i32 { return invokeMiddlewareHandlerBySlot(0, 0, 0) ? 1 : 0 }\nexport function smoke_invoke_route_compute(): i32 { return invokeRouteHandlerBySlot(1, 0, 0) ? 1 : 0 }\nexport function smoke_invoke_lifecycle_connect(): i32 { return invokeLifecycleHandlerBySlot(3, 0, 0) ? 1 : 0 }\nexport function smoke_invoke_channel_bundle(): usize { return invokeChannelHandlerBySlot(5, 0) }\n`;
}

function instantiateAndRun(wasmFile) {
  const wasm = fs.readFileSync(wasmFile);
  const module = new WebAssembly.Module(wasm);
  const imports = WebAssembly.Module.imports(module);
  const exports = WebAssembly.Module.exports(module);
  const handlerCalls = {};
  const importObject = {
    env: {
      abort(message, file, line, column) {
        throw new Error(`AssemblyScript abort(${message}, ${file}, ${line}, ${column})`);
      }
    },
    pulsewasm_handlers: {}
  };

  for (const imp of imports) {
    if (imp.module === 'pulsewasm_handlers') {
      importObject.pulsewasm_handlers[imp.name] = (...args) => {
        handlerCalls[imp.name] = (handlerCalls[imp.name] || 0) + 1;
        return imp.name === 'bundleChannel' ? 0xC0DE : 0;
      };
    }
  }

  const instance = new WebAssembly.Instance(module, importObject);
  const checkDefs = [
    ['smoke_route_count', 2],
    ['smoke_execution_entry_count', 8],
    ['smoke_handler_binding_count', 7],
    ['smoke_match_get_realtime', 0],
    ['smoke_match_post_compute', 1],
    ['smoke_match_missing', -1],
    ['smoke_scan_get_realtime_first_entry', 0],
    ['smoke_step_get_realtime_first_entry', 0],
    ['smoke_get_realtime_second_entry_after_next', 2],
    ['smoke_get_realtime_route_after_two_nexts', 0],
    ['smoke_post_compute_route_after_next', 1],
    ['smoke_missing_after_auth_next_status', 404],
    ['smoke_handler_slot_exists_auth', 1],
    ['smoke_invoke_middleware_auth', 1],
    ['smoke_invoke_route_compute', 1],
    ['smoke_invoke_lifecycle_connect', 1],
    ['smoke_invoke_channel_bundle', 0xC0DE]
  ];

  const checks = [];
  for (const [name, expected] of checkDefs) {
    const fn = instance.exports[name];
    if (typeof fn !== 'function') {
      checks.push({ name, expected, actual: undefined, status: 'error', message: 'Missing smoke export.' });
      continue;
    }
    let actual;
    let status = 'ok';
    let message;
    try {
      actual = fn();
      if (actual !== expected) {
        status = 'error';
        message = `Expected ${expected}, got ${actual}.`;
      }
    } catch (error) {
      status = 'error';
      message = error && error.message ? error.message : String(error);
    }
    checks.push({ name, expected, actual, status, message });
  }

  const requiredHandlerCalls = ['auth', 'computeHandler', 'onConnect', 'bundleChannel'];
  for (const name of requiredHandlerCalls) {
    const actual = handlerCalls[name] || 0;
    checks.push({
      name: `handler_import_${name}_called`,
      expected: 1,
      actual,
      status: actual >= 1 ? 'ok' : 'error',
      message: actual >= 1 ? undefined : `Expected handler import ${name} to be invoked at least once.`
    });
  }

  return {
    imports,
    exports,
    checks,
    handlerCalls,
    memoryExported: Boolean(instance.exports.memory),
    instanceExports: Object.keys(instance.exports)
  };
}

function buildArtifact(options = {}) {
  const diagnostics = options.diagnostics || [];
  const checks = options.smoke?.checks || [];
  const failedChecks = checks.filter((check) => check.status !== 'ok');
  const cwd = options.cwd || process.cwd();
  return normalizeArtifact({
    version: ASSEMBLYSCRIPT_WASM_SMOKE_VERSION,
    generatedBy: options.generatedBy || PACKAGE_VERSION,
    status: options.status || (diagnostics.length || failedChecks.length ? 'error' : 'ok'),
    sourceAssemblyScriptShapeVersion: options.shape?.artifact?.version,
    sourceAssemblyScriptCoreVersion: options.core?.artifact?.version,
    sourceAssemblyScriptCompileVersion: options.compile?.artifact?.version,
    policy: {
      phase: '9F',
      sourceOfTruth: 'generated/as/*.as.ts + generated/as-smoke/smoke-runner.as.ts',
      reReadsSource: false,
      reInfersRouteSemantics: false,
      compiler: 'assemblyscript asc',
      wasmCompiled: true,
      wasmInstantiated: Boolean(options.smoke),
      wasmExecuted: Boolean(options.smoke),
      hostBindings: false,
      witBindings: false,
      platformBindings: false,
      handlerImports: 'local stubs only; this is not host/platform binding',
      stringAbi: 'not finalized; smoke runner uses AssemblyScript string literals internally'
    },
    compiler: {
      package: 'assemblyscript',
      version: options.assemblyScriptVersion,
      executable: options.asc?.display
    },
    command: options.command,
    result: options.result,
    generated: {
      inputFiles: options.stagedFiles || [],
      outputFiles: options.outputs || []
    },
    wasmModule: options.smoke ? {
      imports: options.smoke.imports,
      exports: options.smoke.exports,
      memoryExported: options.smoke.memoryExported
    } : undefined,
    smoke: options.smoke ? {
      checks,
      handlerCalls: options.smoke.handlerCalls,
      instanceExports: options.smoke.instanceExports
    } : undefined,
    diagnostics,
    warnings: options.warnings || [],
    summary: {
      compiled: options.compiled === true,
      instantiated: Boolean(options.smoke),
      executed: Boolean(options.smoke),
      smokePassed: diagnostics.length === 0 && failedChecks.length === 0 && Boolean(options.smoke),
      checks: checks.length,
      failedChecks: failedChecks.length,
      inputFiles: (options.stagedFiles || []).length,
      outputFiles: (options.outputs || []).length,
      wasmBytes: (options.outputs || []).find((file) => file.kind === 'wasm-local-smoke-output')?.bytes || 0,
      watBytes: (options.outputs || []).find((file) => file.kind === 'wat-local-smoke-output')?.bytes || 0,
      diagnostics: diagnostics.length,
      warnings: (options.warnings || []).length,
      hostBindings: false
    }
  }, cwd);
}

function buildAssemblyScriptWasmSmoke(assemblyScriptShape, assemblyScriptCore, assemblyScriptCompile, options = {}) {
  const cwd = options.cwd || process.cwd();
  const outDir = options.outDir || getDefaultArtifactsDir(cwd);
  const diagnostics = [];
  const asc = resolveAsc(cwd);
  const smokeRunnerText = buildSmokeRunnerSource();

  if (!assemblyScriptShape || !assemblyScriptCore) {
    diagnostics.push({
      phase: 'assemblyscript-wasm-smoke',
      code: 'PULSEWASM_WASM_SMOKE_REQUIRES_AS_CORE',
      severity: 'error',
      message: 'AssemblyScript Wasm smoke execution requires generated AS shape and core artifacts.',
      loc: { file: '<assemblyscript-wasm-smoke>' }
    });
  }
  if (!asc) {
    diagnostics.push({
      phase: 'assemblyscript-wasm-smoke',
      code: 'PULSEWASM_WASM_SMOKE_ASC_MISSING',
      severity: 'error',
      message: 'AssemblyScript compiler dependency was not found.',
      hint: 'Run npm install so the assemblyscript devDependency is available.',
      loc: { file: '<assemblyscript-wasm-smoke>' }
    });
  }

  if (diagnostics.length > 0) {
    const artifact = buildArtifact({ cwd, outDir, status: 'error', diagnostics, shape: assemblyScriptShape, core: assemblyScriptCore, compile: assemblyScriptCompile });
    return { version: ASSEMBLYSCRIPT_WASM_SMOKE_VERSION, artifact, diagnostics, files: [{ file: SMOKE_RUNNER_FILE, text: smokeRunnerText }], outputFiles: [] };
  }

  const stagingDir = fs.mkdtempSync(path.join(os.tmpdir(), 'pulsewasm-wasm-smoke-'));
  const outputDir = path.join(outDir, 'generated', 'wasm-smoke');
  fs.mkdirSync(outputDir, { recursive: true });

  const stagedFiles = writeStagedFiles(stagingDir, assemblyScriptShape, assemblyScriptCore, smokeRunnerText);
  const entry = path.join(stagingDir, SMOKE_RUNNER_FILE);
  const wasmFile = path.join(outputDir, 'pulsewasm-local-smoke.wasm');
  const watFile = path.join(outputDir, 'pulsewasm-local-smoke.wat');
  const ascArgs = [
    asc.script,
    entry,
    '--outFile', wasmFile,
    '--textFile', watFile,
    '--runtime', 'stub',
    '--noAssert'
  ];

  const startedAt = Date.now();
  const proc = spawnSync(asc.executable, ascArgs, { cwd, encoding: 'utf8', maxBuffer: 1024 * 1024 * 12 });
  const durationMs = Date.now() - startedAt;
  const warnings = parseAscWarnings(proc.stderr);

  if (proc.error) {
    diagnostics.push({
      phase: 'assemblyscript-wasm-smoke',
      code: 'PULSEWASM_WASM_SMOKE_COMPILE_SPAWN_FAILED',
      severity: 'error',
      message: `Failed to start AssemblyScript compiler: ${proc.error.message}`,
      loc: { file: '<assemblyscript-wasm-smoke>' }
    });
  } else if (proc.status !== 0) {
    diagnostics.push({
      phase: 'assemblyscript-wasm-smoke',
      code: 'PULSEWASM_WASM_SMOKE_COMPILE_FAILED',
      severity: 'error',
      message: `AssemblyScript Wasm smoke runner compile failed with exit code ${proc.status}.`,
      hint: 'Inspect assemblyscript-wasm-smoke.json stderr/stdout for asc diagnostics.',
      loc: { file: '<assemblyscript-wasm-smoke>' },
      details: { exitCode: proc.status, stderr: truncate(proc.stderr, 8000), stdout: truncate(proc.stdout, 8000) }
    });
  }

  const outputs = [];
  if (fs.existsSync(wasmFile)) outputs.push(fileRecord(wasmFile, cwd, 'wasm-local-smoke-output'));
  if (fs.existsSync(watFile)) outputs.push(fileRecord(watFile, cwd, 'wat-local-smoke-output'));

  let smoke;
  if (diagnostics.length === 0 && fs.existsSync(wasmFile)) {
    try {
      smoke = instantiateAndRun(wasmFile);
      const failedChecks = smoke.checks.filter((check) => check.status !== 'ok');
      if (failedChecks.length > 0) {
        diagnostics.push({
          phase: 'assemblyscript-wasm-smoke',
          code: 'PULSEWASM_WASM_SMOKE_CHECK_FAILED',
          severity: 'error',
          message: `${failedChecks.length} compiled Wasm smoke check(s) failed.`,
          hint: 'Inspect assemblyscript-wasm-smoke.json smoke.checks for failed exports.',
          loc: { file: '<assemblyscript-wasm-smoke>' },
          details: { failedChecks }
        });
      }
    } catch (error) {
      diagnostics.push({
        phase: 'assemblyscript-wasm-smoke',
        code: 'PULSEWASM_WASM_SMOKE_INSTANTIATE_FAILED',
        severity: 'error',
        message: `Compiled Wasm smoke module could not be instantiated/executed: ${error && error.message ? error.message : String(error)}`,
        loc: { file: '<assemblyscript-wasm-smoke>' }
      });
    }
  }

  const artifact = buildArtifact({
    cwd,
    outDir,
    status: diagnostics.length === 0 ? 'ok' : 'error',
    diagnostics,
    warnings,
    shape: assemblyScriptShape,
    core: assemblyScriptCore,
    compile: assemblyScriptCompile,
    asc,
    assemblyScriptVersion: assemblyScriptVersion(cwd),
    stagedFiles,
    outputs,
    smoke,
    compiled: proc.status === 0,
    command: {
      executable: asc.display,
      args: ascArgs.slice(1).map((arg) => path.isAbsolute(arg) ? path.relative(cwd, arg).replace(/\\/g, '/') : arg)
    },
    result: {
      exitCode: proc.status,
      signal: proc.signal,
      durationMs,
      stdout: truncate(proc.stdout),
      stderr: truncate(proc.stderr)
    }
  });

  return {
    version: ASSEMBLYSCRIPT_WASM_SMOKE_VERSION,
    artifact,
    diagnostics,
    files: [{ file: SMOKE_RUNNER_FILE, text: smokeRunnerText }],
    outputFiles: outputs
  };
}

module.exports = {
  ASSEMBLYSCRIPT_WASM_SMOKE_VERSION,
  SMOKE_RUNNER_FILE,
  SMOKE_WASM_FILE,
  SMOKE_WAT_FILE,
  buildAssemblyScriptWasmSmoke,
  buildSmokeRunnerSource
};
